update yc_topic
venue_id=#{venueId}, topic_name=#{topicName}, start_time=#{startTime}, end_time=#{endTime}, chair_names=#{chairNames}, host_names=#{hostNames}, discuss_names=#{discussNames}, sort_order=#{sortOrder}, update_by=#{updateBy}, remark=#{remark}, update_time=sysdate()
where topic_id=#{topicId}
